public AuthorizationTuple Decode(RlpStream stream, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
{
    int length = stream.ReadSequenceLength();
    int check = length + stream.Position;
    UInt256 chainId = stream.DecodeUInt256();        // field 1
    Address? codeAddress = stream.DecodeAddress();   // field 2
    ulong nonce = stream.DecodeULong();              // field 3
    byte yParity = stream.DecodeByte();              // field 4
    UInt256 r = stream.DecodeUInt256();              // field 5
    UInt256 s = stream.DecodeUInt256();              // field 6

    if (!rlpBehaviors.HasFlag(RlpBehaviors.AllowExtraBytes))
        stream.Check(check);  // enforces no extra fields

    if (codeAddress is null)
        ThrowMissingCodeAddressException();

    return new AuthorizationTuple(chainId, codeAddress, nonce, yParity, r, s);
}

